     1	import {describe, expect, it} from '@jest/globals';
     2	import {createChatOrchestrator} from './chatOrchestrator.js';
     3	import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
     4	import type {ChatSession} from '../types/session.js';
     5	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
     6	
     7	const SENT_AT = '2026-01-01T00:00:00.000Z';
     8	
     9	function createSession(content: string): ChatSession {
    10	  return {
    11	    sessionId: 's1',
    12	    userId: 'u1',
    13	    entries: [{role: 'user', content, timestamp: SENT_AT}],
    14	  };
    15	}
    16	
    17	function createMockProvider(response: string): AIProvider {
    18	  return {
    19	    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    20	      yield {type: 'text', text: response};
    21	      yield {type: 'stop', stopReason: 'end_turn'};
    22	    },
    23	    async generateStructured<T>(): Promise<T> {
    24	      return {} as T;
    25	    },
    26	  };
    27	}
    28	
    29	const promptBuilder = new PromptBuilder({identity: 'You are HAL.'});
    30	
    31	describe('beforeSession throwing', () => {
    32	  it('runs onError and afterSession when beforeSession throws', async () => {
    33	    const errorToThrow = new Error('Database connection failed in beforeSession');
    34	
    35	    let caughtError: Error | undefined;
    36	    let afterSessionRan = false;
    37	
    38	    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
    39	      hooks: {
    40	        beforeSession: async () => {
    41	          throw errorToThrow;
    42	        },
    43	        onError: async (_session, error) => {
    44	          caughtError = error;
    45	        },
    46	        afterSession: async () => {
    47	          afterSessionRan = true;
    48	        },
    49	      },
    50	    });
    51	
    52	    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
    53	      'Database connection failed in beforeSession'
    54	    );
    55	
    56	    expect({caughtError, afterSessionRan}).toEqual({caughtError: errorToThrow, afterSessionRan: true});
    57	  });
    58	});
26:- `beforeSession` is inside the `try` block, so a throw there reaches the `catch`/`finally` blocks, firing both `onError` and `afterSession`, where a deployer can assume no tools were run and the turn was aborted before provider interaction ([validated by: runs onError and afterSession when beforeSession throws](../../src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts#L40)).

